class Solution {
public:
    long long countFairPairs(std::vector<int>& nums, int lower, int upper) {
        std::sort(nums.begin(), nums.end());
        auto countLessEqual = [&](long long val) -> long long {
            long long res = 0;
            int i = 0, j = (int)nums.size() - 1;
            while (i < j) {
                if (nums[i] + nums[j] <= val) {
                    res += (j - i);
                    i++;
                } else {
                    j--;
                }
            }
            return res;
        };
        return countLessEqual(upper) - countLessEqual((long long)lower - 1);
    }
};

class Solution {
    public long countFairPairs(int[] nums, int lower, int upper) {
        java.util.Arrays.sort(nums);
        return countLessEqual(nums, upper) - countLessEqual(nums, lower - 1);
    }

    private long countLessEqual(int[] nums, long val) {
        long res = 0;
        int i = 0, j = nums.length - 1;
        while (i < j) {
            if (nums[i] + nums[j] <= val) {
                res += (j - i);
                i++;
            } else {
                j--;
            }
        }
        return res;
    }
}

var countFairPairs = function(nums, lower, upper) {
    nums.sort((a, b) => a - b);
    const countLessEqual = (val) => {
        let res = 0;
        let i = 0, j = nums.length - 1;
        while (i < j) {
            if (nums[i] + nums[j] <= val) {
                res += (j - i);
                i++;
            } else {
                j--;
            }
        }
        return res;
    };
    return countLessEqual(upper) - countLessEqual(lower - 1);
};
